<?php
namespace App\Http\Controllers;
use App\Models\{Order,Product,Coupon};use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class CheckoutController extends Controller{
 public function index(){ $cart=session('cart',[]);if(!$cart)return redirect()->route('cart')->withErrors(['cart'=>'Giỏ hàng đang trống.']);$subtotal=collect($cart)->sum(fn($i)=>$i['price']*$i['quantity']);$coupon=session('coupon');$discount=0;if($coupon&&($c=Coupon::where('code',$coupon)->first()))$discount=$c->discountFor($subtotal);$shipping=$subtotal>=500000?0:30000;$total=max(0,$subtotal+$shipping-$discount);return view('store.checkout',compact('cart','subtotal','coupon','discount','shipping','total'));}
 public function applyCoupon(Request $r){$d=$r->validate(['code'=>'required|string|max:40']);$c=Coupon::where('code',strtoupper(trim($d['code'])))->first();$subtotal=collect(session('cart',[]))->sum(fn($i)=>$i['price']*$i['quantity']);if(!$c||$c->discountFor($subtotal)<=0)return back()->withErrors(['coupon'=>'Mã giảm giá không hợp lệ hoặc không đủ điều kiện.']);session(['coupon'=>$c->code]);return back()->with('success','Đã áp dụng mã '.$c->code);}
 public function removeCoupon(){session()->forget('coupon');return back()->with('success','Đã bỏ mã giảm giá.');}
 public function place(Request $r){$data=$r->validate(['customer_name'=>'required|string|max:120','email'=>'required|email','phone'=>'required|string|max:30','address'=>'required|string|max:500','payment_method'=>'required|in:COD,VNPAY,MOMO','notes'=>'nullable|string|max:1000']);$cart=session('cart',[]);if(!$cart)return redirect()->route('cart')->withErrors(['cart'=>'Giỏ hàng đang trống.']);$order=DB::transaction(function()use($cart,$data,$r){$subtotal=0;$rows=[];foreach($cart as $id=>$item){$p=Product::lockForUpdate()->findOrFail($id);$qty=(int)$item['quantity'];if(!$p->is_active||$p->stock<$qty)throw ValidationException::withMessages(['cart'=>"{$p->name} không đủ tồn kho."]);$price=(float)$p->current_price;$subtotal+=$price*$qty;$rows[]=[$p,$qty,$price];}$couponCode=session('coupon');$coupon=$couponCode?Coupon::where('code',$couponCode)->lockForUpdate()->first():null;$discount=$coupon? $coupon->discountFor($subtotal):0;if($couponCode&&!$discount)throw ValidationException::withMessages(['coupon'=>'Mã giảm giá không còn hiệu lực.']);$shipping=$subtotal>=500000?0:30000;$o=Order::create(['user_id'=>$r->user()?->id,'order_code'=>'PURE'.now()->format('ymd').Str::upper(Str::random(6)),'customer_name'=>$data['customer_name'],'email'=>$data['email'],'phone'=>$data['phone'],'address'=>$data['address'],'subtotal'=>$subtotal,'shipping_fee'=>$shipping,'discount'=>$discount,'total'=>max(0,$subtotal+$shipping-$discount),'payment_method'=>$data['payment_method'],'payment_status'=>'pending','status'=>'pending','notes'=>$data['notes']??null]);foreach($rows as [$p,$qty,$price]){$o->items()->create(['product_id'=>$p->id,'product_name'=>$p->name,'price'=>$price,'quantity'=>$qty,'line_total'=>$price*$qty]);$p->decrement('stock',$qty);}if($coupon)$coupon->increment('used_count');return $o;});session(['guest_order_'.$order->id=>true]);session()->forget(['cart','coupon']);if($order->payment_method==='COD')return redirect()->route('checkout.success',$order)->with('success','Đặt hàng thành công!');return redirect()->route('payment.start',$order);}
 public function success(Order $order){if(auth()->id()!==$order->user_id&&!session('guest_order_'.$order->id))abort(403);$order->load('items');return view('store.success',compact('order'));}
 public function history(){abort_unless(auth()->check(),401);$orders=auth()->user()->orders()->with('items')->latest()->paginate(10);return view('store.orders',compact('orders'));}
}
